console.log(odejmij(10, 4)); // 6

function odejmij(a, b) {
  return a - b;
}

const podziel = function (a, b) {
  return a / b;
};

console.log(podziel(20, 4)); // 5

// gdyby wywolac pomnoz(2, 3) PRZED ponizsza linia, JavaScript zglosilby
// TypeError: pomnoz is not a function - zmienna pomnoz istnieje
// dopiero OD linii przypisania, nie jest hoistowana jak function declaration

const pomnoz = function (a, b) {
  return a * b;
};

console.log(pomnoz(2, 3)); // 6

function policzSrednia(a, b, c) {
  return (a + b + c) / 3;
}

console.log(policzSrednia(2, 4, 6));   // 4
console.log(policzSrednia(10, 20, 30)); // 20

const policzPole = function (bok) {
  return bok * bok;
};

console.log(policzPole(5)); // 25

console.log(obliczCene(100, 0.23)); // 123

function obliczCene(cenaBazowa, podatek) {
  return cenaBazowa + cenaBazowa * podatek;
}

const kalkulator = {
  dodaj: function (a, b) { return a + b; },
  odejmij: function (a, b) { return a - b; }
};

console.log(kalkulator.dodaj(10, 5));    // 15
console.log(kalkulator.odejmij(10, 5));  // 5

try {
  console.log(przedstawWynik(42));
} catch (e) {
  console.log(e.name); // "TypeError"
}

const przedstawWynik = function (wynik) {
  return `Wynik to: ${wynik}`;
};

console.log(przedstawWynik(42)); // "Wynik to: 42" - POPRAWNIE, po deklaracji
